class Solution {
public:
    int maxDistToClosest(vector<int>& seats) {
        int n = seats.size();
        int ans = 0;

        int first = -1;
        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                first = i;
                break;
            }
        }
        ans = first;

        int last = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (seats[i] == 1) {
                last = i;
                break;
            }
        }
        ans = max(ans, n - 1 - last);

        int prev = first;
        for (int i = first + 1; i <= last; i++) {
            if (seats[i] == 1) {
                int gap = i - prev;
                ans = max(ans, gap / 2);
                prev = i;
            }
        }

        return ans;
    }
};
